function bsample(data,w,h,x,y){
  if(x<0)x=0; else if(x>w-1)x=w-1;
  if(y<0)y=0; else if(y>h-1)y=h-1;
  var x0=Math.floor(x), y0=Math.floor(y);
  var x1=x0+1, y1=y0+1;
  if(x1>w-1)x1=w-1; if(y1>h-1)y1=h-1;
  var fx=x-x0, fy=y-y0;
  var i00=(y0*w+x0)*4, i10=(y0*w+x1)*4, i01=(y1*w+x0)*4, i11=(y1*w+x1)*4;
  var o0=data[i00]+(data[i10]-data[i00])*fx;
  var o1=data[i01]+(data[i11]-data[i01])*fx;
  var r=o0+(o1-o0)*fy;
  var g0=data[i00+1]+(data[i10+1]-data[i00+1])*fx;
  var g1=data[i01+1]+(data[i11+1]-data[i01+1])*fx;
  var g=g0+(g1-g0)*fy;
  var b0=data[i00+2]+(data[i10+2]-data[i00+2])*fx;
  var b1=data[i01+2]+(data[i11+2]-data[i01+2])*fx;
  var b=b0+(b1-b0)*fy;
  var a0=data[i00+3]+(data[i10+3]-data[i00+3])*fx;
  var a1=data[i01+3]+(data[i11+3]-data[i01+3])*fx;
  var a=a0+(a1-a0)*fy;
  return [r,g,b,a];
}

function liquifyProcess(data,w,h,opts){
  opts=opts||{};
  var strokes=opts.strokes||[], radius=opts.radius||20, falloff=opts.falloff!=null?opts.falloff:1;
  var out=new Uint8ClampedArray(data.length);
  out.set(data);
  var dispX=new Float32Array(w*h), dispY=new Float32Array(w*h);
  for(var s=0;s<strokes.length;s++){
    var st=strokes[s], dx=st.dx||0, dy=st.dy||0, px=st.x, py=st.y, rr=radius;
    var x0=Math.max(0,Math.floor(px-rr)), x1=Math.min(w-1,Math.ceil(px+rr));
    var y0=Math.max(0,Math.floor(py-rr)), y1=Math.min(h-1,Math.ceil(py+rr));
    for(var y=y0;y<=y1;y++) for(var x=x0;x<=x1;x++){
      var ex=x-px, ey=y-py, dd=Math.sqrt(ex*ex+ey*ey);
      if(dd<=rr){ var wgt=(1-dd/rr)*falloff, idx=y*w+x; dispX[idx]+=dx*wgt; dispY[idx]+=dy*wgt; }
    }
  }
  for(var y2=0;y2<h;y2++) for(var x2=0;x2<w;x2++){
    var idx2=y2*w+x2, nx=x2+dispX[idx2], ny=y2+dispY[idx2];
    var ss=bsample(data,w,h,nx,ny), i=(y2*w+x2)*4;
    out[i]=ss[0];out[i+1]=ss[1];out[i+2]=ss[2];out[i+3]=ss[3];
  }
  return out;
}

var EXPORTS={liquifyProcess:liquifyProcess};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LiquifyForgePure = EXPORTS; }
